    "instructions": [
      {
        "sequence": 1,
        "text": "Smula ner jästen i en bunke. Ljumma vattnet till 37 grader (fingervarmt), häll lite av det över jästen och rör om tills det löst sig."
      },
      {
        "sequence": 2,
        "text": "Tillsätt resten av vattnet, salt, olja och vetemjöl och arbeta degen smidig. Degen ska vara ganska lös. Jäs under duk i cirka 40 minuter."
      },
      {
        "sequence": 3,
        "text": "Tryck ut degen i en oljad långpanna och låt jäsa ytterligare 35 minuter. Sätt under tiden ugnen på 225 grader."
      },
      {
        "sequence": 4,
        "text": "Strö över rosmarinen och den skivade vitlöken. Tryck till lite. Salta och stänk över olivolja."
      },
      {
        "sequence": 5,
        "text": "Grädda i mitten av ugnen i cirka 15 minuter."
      }
    ]
