        "text": "Koka kycklingen tillsammans med 2 grovt hackade vårlökar, tunt skivad ingefära, buljong och sichuanpeppar i ca 10 - 15 minuter, eller tills den känns färdig (70 grader). Skumma av och stäng av spisen, häll av vattnet och låt kycklingen ligga och vila i 10 minuter. "
