    "instructions": [
      {
        "sequence": 1,
        "text": "Dela blomkålen i mindre bitar och koka i vatten och 1 msk salt i ca 3 - 4 minuter. Lägg över i ett durkslag "
      },
      {
        "sequence": 2,
        "text": "Blanda 4 msk majsmjöl, 4 msk vetemjöl och en tsk salt. Häll på lite vatten och blanda till en tjock smet. Lägg i blomkålen och blanda väl med händerna. Häll på ytterligare 2 msk majsmjöl och 1 msk vetmjöl och blanda. "
      },
      {
        "sequence": 3,
        "text": "Fritera på medelvärme. Stoppa ner blomkålen en och en så dom inte klibbar ihop. När blomkålen flyter upp är den färdig. Den ska få lite färg. Ta upp och lägg på en tallrik (har dom fastnat, försök att ta isär dom)."
      },
      {
        "sequence": 4,
        "text": "Öka värmen på woken och i med blomkålen så den blir brynt. Lägg på en tallrik"
      },
      {
        "sequence": 5,
        "text": "Häll av det mesta av oljan, men spara 3 msk. Hög värme och i med vitlök, chili och lök och stek i ca 1 min. Salta och peppra."
      },
      {
        "sequence": 6,
        "text": "Häll i chilisås och soja och blanda. I med vårlök och ketchup och blanda."
      },
      {
        "sequence": 7,
        "text": "Blanda 1 tsk majsmjöl med 2 msk vatten in skål. Häll på 1 dl vatten i woken och tillsätt mjöl och vettenblandningen en tesked i taget och blanda hela tiden. När såsen har tjocknat, häll i blomkålen och blanda väl."
      }
    ]
