    "instructions": [
      {
        "sequence": 1,
        "text": "Skala en lök, vitlök och ingefära"
      },
      {
        "sequence": 2,
        "text": "Dela tomaterna i klyftor"
      },
      {
        "sequence": 3,
        "text": "Lägg lök, vitlök, ingefära, tomat, fänkålsfrön, spiskumminfrön och hälften av koriandern i matberedaren och mal till en fin pasta"
      },
      {
        "sequence": 4,
        "text": "Skala och finhacka den andra löken"
      },
      {
        "sequence": 5,
        "text": "Hetta upp olja och smör i en panna"
      },
      {
        "sequence": 6,
        "text": "Fräs kanel, kryddnejlika och lök"
      },
      {
        "sequence": 7,
        "text": "Tillsätt currybladen efter en stund och fräs tills löken mjuknat"
      },
      {
        "sequence": 8,
        "text": "Tillsätt pastan och fräs tills färgen mörknat lite"
      },
      {
        "sequence": 9,
        "text": "Tillsätt chilipulver, koriander, garam masala, gurkmeja och salt och fräs tills den råa doften försvunnit"
      },
      {
        "sequence": 10,
        "text": "Tillsätt lammfärsen och fräs i 5 minuter"
      },
      {
        "sequence": 11,
        "text": "Tillsätt vatten så att det täcker köttfärsen och koka under lock i 20-30 minuter. Nu är det också dags att sätta på riset."
      },
      {
        "sequence": 12,
        "text": "Plocka bladen från koriandern"
      },
      {
        "sequence": 13,
        "text": "Sätt av värmen och tillsätt korianderbladen"
      }
    ]
